mapper.select:
SELECT id, user_id, device_id, jti, parent_jti, expires_at, revoked_at, created_at
FROM refresh_tokens
WHERE jti = #{jti}

SELECT COUNT(*)
FROM refresh_tokens
WHERE parent_jti = #{jti}

mapper.update:
UPDATE refresh_tokens
SET revoked_at = #{revokedAt}
WHERE jti = #{jti}
  AND revoked_at IS NULL

UPDATE refresh_tokens
SET revoked_at = #{revokedAt}
WHERE user_id = #{userId}
  AND revoked_at IS NULL

UPDATE refresh_tokens
SET revoked_at = #{revokedAt}
WHERE user_id = #{userId}
  AND device_id = #{deviceId}
  AND revoked_at IS NULL
